1	import Phaser from 'phaser';
2	import { MIN_TAP_TARGET_PX } from '../config/gameConfig';
3	
4	/** Hover/press scale feedback (presentation feel; kept as before). */
5	const HOVER_SCALE = 1.04;
6	const PRESS_SCALE = 0.96;
7	
8	/** Any interactive, sizeable GameObject we can grow a hit area on (Image OR Text). */
9	type HitAreaTarget = Phaser.GameObjects.Image | Phaser.GameObjects.Text;
10	
11	/**
12	 * enlargeHitArea — give an Image or Text object (e.g. a small icon button, or a
13	 * bare text button) a CENTERED hit area of at least `size` logical px on each axis,
14	 * so it clears the comfortable tap-target guideline even after the 1280×720 canvas
15	 * is FIT-scaled down on a phone. The rectangle is expressed in the object's local
16	 * space (origin at the frame/bounds top-left, which is what Phaser's hit test
17	 * expects) and stays centered on the art/text regardless of the object's display
18	 * origin. Idempotent — safe to call again to re-enable interactivity after
19	 * `disableInteractive()`.
20	 */
21	export function enlargeHitArea(target: HitAreaTarget, size = MIN_TAP_TARGET_PX): void {
22	  const w = Math.max(target.width, size);
23	  const h = Math.max(target.height, size);
24	  target.setInteractive(
25	    new Phaser.Geom.Rectangle((target.width - w) / 2, (target.height - h) / 2, w, h),
26	    Phaser.Geom.Rectangle.Contains,
27	  );
28	  if (target.input) target.input.cursor = 'pointer';
29	}
30	
31	/**
32	 * createButton — a small reusable button factory used across scenes (Play, CTA,
33	 * Play-again, the Phase-1 debug finish buttons). Backed by an SVG texture when
34	 * one is given, otherwise a drawn rectangle (handy for temporary/debug buttons).
35	 * Returns an interactive Container with hover/press feedback.
36	 */
37	export interface ButtonOptions {
38	  x: number;
39	  y: number;
40	  onClick: () => void;
41	  /** Background texture key. If omitted, a rectangle is drawn instead. */
42	  texture?: string;
43	  /** Centered label text. */
44	  label?: string;
45	  /** Explicit hit size; defaults to the texture size, or 220×64 for the rect. */
46	  width?: number;
47	  height?: number;
48	  /** Overrides merged onto the default label text style. */
49	  labelStyle?: Phaser.Types.GameObjects.Text.TextStyle;
50	}
51	
52	const DEFAULT_LABEL_STYLE: Phaser.Types.GameObjects.Text.TextStyle = {
53	  fontFamily: 'system-ui, sans-serif',
54	  fontSize: '26px',
55	  fontStyle: 'bold',
56	  color: '#f4f7fa',
57	};
58	
59	export function createButton(scene: Phaser.Scene, opts: ButtonOptions): Phaser.GameObjects.Container {
60	  const container = scene.add.container(opts.x, opts.y);
61	
62	  let width = opts.width ?? 0;
63	  let height = opts.height ?? 0;
64	
65	  if (opts.texture) {
66	    const bg = scene.add.image(0, 0, opts.texture).setOrigin(0.5);
67	    width = width || bg.width;
68	    height = height || bg.height;
69	    container.add(bg);
70	  } else {
71	    width = width || 220;
72	    height = height || 64;
73	    const rect = scene.add
74	      .rectangle(0, 0, width, height, 0x2b3a46)
75	      .setStrokeStyle(2, 0x5b6670)
76	      .setOrigin(0.5);
77	    container.add(rect);
78	  }
79	
80	  if (opts.label !== undefined) {
81	    const style: Phaser.Types.GameObjects.Text.TextStyle = { ...DEFAULT_LABEL_STYLE, ...opts.labelStyle };
82	    const text = scene.add.text(0, 0, opts.label, style).setOrigin(0.5);
83	    container.add(text);
84	  }
85	
86	  // The hit area is the VISIBLE art, expanded to a comfortable minimum tap target
87	  // on each axis (never smaller). The SVG is rasterized to its manifest size, so
88	  // bg.width/height == the displayed frame; the art fills that frame (only a few
89	  // px of transparent padding), so a frame-sized-or-larger rect covers the whole
90	  // visible button. The rect is in the container's local space and Phaser applies
91	  // the container transform during hit-testing, so the press/hover SCALE never
92	  // shifts the effective hit region off the button.
93	  const hitW = Math.max(width, MIN_TAP_TARGET_PX);
94	  const hitH = Math.max(height, MIN_TAP_TARGET_PX);
95	  container.setSize(hitW, hitH);
96	  container.setInteractive(
97	    new Phaser.Geom.Rectangle(-hitW / 2, -hitH / 2, hitW, hitH),
98	    Phaser.Geom.Rectangle.Contains,
99	  );
100	  if (container.input) {
101	    container.input.cursor = 'pointer';
102	  }
103	
104	  container.on(Phaser.Input.Events.POINTER_OVER, () => container.setScale(HOVER_SCALE));
105	  container.on(Phaser.Input.Events.POINTER_OUT, () => container.setScale(1));
106	  container.on(Phaser.Input.Events.POINTER_DOWN, () => container.setScale(PRESS_SCALE));
107	  // Reset to the resting scale on release. On TOUCH there is no POINTER_OUT after
108	  // a tap, so returning to the hover scale would leave the control stuck enlarged
109	  // — snap back to 1; on mouse, keep the hover scale since the cursor is still on
110	  // the button. POINTER_OUT already handles press-then-drag-off (→ scale 1).
111	  container.on(Phaser.Input.Events.POINTER_UP, (pointer: Phaser.Input.Pointer) => {
112	    container.setScale(pointer.wasTouch ? 1 : HOVER_SCALE);
113	    opts.onClick();
114	  });
115	
116	  return container;
117	}
