67	
68	  private buildMuteToggle(): void {
69	    const muteBtn = this.add.image(GAME_WIDTH - 52, 52, this.muteTexture());
70	    enlargeHitArea(muteBtn); // full-icon + comfortable tap target (§10.4)
71	
72	    const label = this.add
73	      .text(GAME_WIDTH - 52, 90, this.muteLabel(), {
74	        fontFamily: 'system-ui, sans-serif',
75	        fontSize: '14px',
76	        color: '#9fb0bd',
77	      })
78	      .setOrigin(0.5, 0);
79	
80	    muteBtn.on(Phaser.Input.Events.POINTER_UP, () => {
81	      AudioManager.toggle(this.sound);
82	      muteBtn.setTexture(this.muteTexture());
83	      label.setText(this.muteLabel());
84	      playSfx(this, Sfx.ui);
85	    });
86	  }
87	
88	  private muteTexture(): string {
89	    return AudioManager.isMuted() ? KEYS.ui_btn_mute_off : KEYS.ui_btn_mute_on;
90	  }
91	
92	  private muteLabel(): string {
93	    return AudioManager.isMuted() ? t('menu_sound_off') : t('menu_sound_on');
94	  }
