96	  private buildPromoCopyChip(x: number, y: number): void {
97	    const container = this.add.container(x, y);
98	    const chip = this.add.image(0, 0, KEYS.ui_promo_chip).setOrigin(0.5);
99	    const text = this.add
100	      .text(0, 0, `${t('results_promo_label')} ${ENV.promoCode}`, {
101	        fontFamily: 'monospace',
102	        fontSize: '24px',
103	        fontStyle: 'bold',
104	        color: '#20272e',
105	      })
106	      .setOrigin(0.5);
107	    container.add([chip, text]);
108	    // Match the hit area to the ACTUAL chip art (460×120) — the old 400×100 left
109	    // the pill's outer edges dead — floored to the comfortable tap target.
110	    const hitW = Math.max(chip.width, MIN_TAP_TARGET_PX);
111	    const hitH = Math.max(chip.height, MIN_TAP_TARGET_PX);
112	    container.setSize(hitW, hitH);
113	    container.setInteractive(
114	      new Phaser.Geom.Rectangle(-hitW / 2, -hitH / 2, hitW, hitH),
115	      Phaser.Geom.Rectangle.Contains,
116	    );
117	    if (container.input) container.input.cursor = 'pointer';
118	    container.on(Phaser.Input.Events.POINTER_UP, () => this.copyPromoCode());
119	  }
120	
121	  private async copyPromoCode(): Promise<void> {
122	    try {
123	      if (!navigator.clipboard) {
124	        return; // feature unavailable, silent no-op
125	      }
126	      await navigator.clipboard.writeText(ENV.promoCode);
127	      playSfx(this, Sfx.ui);
128	      this.showCopyConfirmation();
129	    } catch {
130	      // copy failed (e.g., no permission), silent no-op
131	      return;
132	    }
133	  }
134	
135	  private showCopyConfirmation(): void {
136	    const cx = GAME_WIDTH / 2;
137	    const label = this.add
138	      .text(cx, 705, t('results_promo_copied'), {
139	        fontFamily: 'system-ui, sans-serif',
140	        fontSize: '14px',
141	        fontStyle: 'bold',
142	        color: '#6cc04a',
143	      })
144	      .setOrigin(0.5)
145	      .setAlpha(1);
146	    this.tweens.add({
147	      targets: label,
148	      alpha: 0,
149	      duration: PROMO_COPY_FADE_MS,
150	      ease: 'Quad.in',
151	      onComplete: () => label.destroy(),
152	    });
153	  }
154	}
