137	        fontFamily: 'system-ui, sans-serif',
138	        fontSize: '16px',
139	        fontStyle: 'bold',
140	        color: '#6cc04a',
141	      })
142	      .setOrigin(0.5)
143	      .setAlpha(1);
144	    this.tweens.add({
145	      targets: label,
146	      alpha: 0,
147	      duration: PROMO_COPY_FADE_MS,
148	      ease: 'Quad.in',
149	      onComplete: () => label.destroy(),
150	    });
151	  }
