30	  const w = Math.max(target.width, size);
31	  const h = Math.max(target.height, size);
32	  target.setInteractive(
33	    new Phaser.Geom.Rectangle((target.width - w) / 2, (target.height - h) / 2, w, h),
34	    Phaser.Geom.Rectangle.Contains,
35	  );
36	  if (target.input) target.input.cursor = 'pointer';
