33	 * Play-again, the Phase-1 debug finish buttons). Backed by an SVG texture when
34	 * one is given, otherwise a drawn rectangle (handy for temporary/debug buttons).
35	 * Returns an interactive Container with hover/press feedback.
36	 */
37	export interface ButtonOptions {
38	  x: number;
39	  y: number;
40	  onClick: () => void;
41	  /** Background texture key. If omitted, a rectangle is drawn instead. */
42	  texture?: string;
43	  /** Centered label text. */
44	  label?: string;
45	  /** Explicit hit size; defaults to the texture size, or 220×64 for the rect. */
46	  width?: number;
47	  height?: number;
48	  /** Overrides merged onto the default label text style. */
49	  labelStyle?: Phaser.Types.GameObjects.Text.TextStyle;
50	}
51	
52	const DEFAULT_LABEL_STYLE: Phaser.Types.GameObjects.Text.TextStyle = {
53	  fontFamily: 'system-ui, sans-serif',
54	  fontSize: '26px',
55	  fontStyle: 'bold',
56	  color: '#f4f7fa',
57	};
