59	export function createButton(scene: Phaser.Scene, opts: ButtonOptions): Phaser.GameObjects.Container {
60	  const container = scene.add.container(opts.x, opts.y);
61	
62	  let width = opts.width ?? 0;
63	  let height = opts.height ?? 0;
64	
65	  if (opts.texture) {
66	    const bg = scene.add.image(0, 0, opts.texture).setOrigin(0.5);
67	    width = width || bg.width;
68	    height = height || bg.height;
69	    container.add(bg);
70	  } else {
71	    width = width || 220;
72	    height = height || 64;
73	    const rect = scene.add
74	      .rectangle(0, 0, width, height, 0x2b3a46)
75	      .setStrokeStyle(2, 0x5b6670)
76	      .setOrigin(0.5);
77	    container.add(rect);
78	  }
79	
80	  if (opts.label !== undefined) {
81	    const style: Phaser.Types.GameObjects.Text.TextStyle = { ...DEFAULT_LABEL_STYLE, ...opts.labelStyle };
82	    const text = scene.add.text(0, 0, opts.label, style).setOrigin(0.5);
83	    container.add(text);
84	  }
85	
86	  // The hit area is the VISIBLE art, expanded to a comfortable minimum tap target
87	  // on each axis (never smaller). The SVG is rasterized to its manifest size, so
88	  // bg.width/height == the displayed frame; the art fills that frame (only a few
89	  // px of transparent padding), so a frame-sized-or-larger rect covers the whole
90	  // visible button. The rect is in the container's local space and Phaser applies
91	  // the container transform during hit-testing, so the press/hover SCALE never
92	  // shifts the effective hit region off the button.
93	  const hitW = Math.max(width, MIN_TAP_TARGET_PX);
94	  const hitH = Math.max(height, MIN_TAP_TARGET_PX);
95	  container.setSize(hitW, hitH);
96	  container.setInteractive(
97	    new Phaser.Geom.Rectangle(-hitW / 2, -hitH / 2, hitW, hitH),
98	    Phaser.Geom.Rectangle.Contains,
99	  );
100	  if (container.input) {
101	    container.input.cursor = 'pointer';
102	  }
103	
104	  container.on(Phaser.Input.Events.POINTER_OVER, () => container.setScale(HOVER_SCALE));
105	  container.on(Phaser.Input.Events.POINTER_OUT, () => container.setScale(1));
106	  container.on(Phaser.Input.Events.POINTER_DOWN, () => container.setScale(PRESS_SCALE));
107	  // Reset to the resting scale on release. On TOUCH there is no POINTER_OUT after
108	  // a tap, so returning to the hover scale would leave the control stuck enlarged
109	  // — snap back to 1; on mouse, keep the hover scale since the cursor is still on
110	  // the button. POINTER_OUT already handles press-then-drag-off (→ scale 1).
111	  container.on(Phaser.Input.Events.POINTER_UP, (pointer: Phaser.Input.Pointer) => {
112	    container.setScale(pointer.wasTouch ? 1 : HOVER_SCALE);
113	    opts.onClick();
114	  });
115	
116	  return container;
117	}
