7	import { createButton, enlargeHitArea } from '../ui/Button';
8	import { ENV, buildBuyUrl, buyDestination } from '../config/env';
9	import { playSfx, Sfx, stopMusic } from '../systems/audio';
10	
11	/**
12	 * ResultsScene — Victory or Game Over depending on the `result` param, the final
13	 * score, the promo-code chip, the buy CTA (fires `click_buy` then opens the
14	 * UTM-tagged buy URL in a new tab), and Play-again (→ a fresh run).
15	 */
16	export class ResultsScene extends Phaser.Scene {
17	  constructor() {
18	    super({ key: SceneKey.Results });
19	  }
20	
21	  create(data: Partial<FinishGameParams> = {}): void {
22	    // Robust if entered without/with partial data (e.g. deep-link, hot reload):
23	    // default to a Game-Over result and a zero score.
24	    const win = data.result === 'win';
25	    const score = typeof data.score === 'number' ? data.score : 0;
26	    const cx = GAME_WIDTH / 2;
27	
28	    // The gameplay loop already stops its music on run-end; this is a defensive
29	    // stop for any entry path (deep-link / hot reload) so Results is silent.
30	    stopMusic();
31	
32	    this.add.image(cx, GAME_HEIGHT / 2, win ? KEYS.screen_bg_victory : KEYS.screen_bg_gameover);
33	    this.add.image(cx, 250, win ? KEYS.dog_victory : KEYS.dog_defeat);
34	
35	    this.add
36	      .text(cx, 90, win ? t('results_victory_title') : t('results_gameover_title'), {
37	        fontFamily: 'system-ui, sans-serif',
38	        fontSize: '48px',
39	        fontStyle: 'bold',
40	        color: '#20272e',
41	      })
42	      .setOrigin(0.5);
43	
44	    this.add
45	      .text(cx, 380, t('results_score', { score }), {
46	        fontFamily: 'system-ui, sans-serif',
47	        fontSize: '30px',
48	        color: '#20272e',
49	      })
50	      .setOrigin(0.5);
51	
52	    // Promo chip + code (tap-to-copy).
53	    this.buildPromoCopyChip(cx, 460);
54	
55	    // The conversion CTA.
56	    createButton(this, {
57	      x: cx,
58	      y: 565,
59	      texture: KEYS.ui_btn_cta,
60	      label: t('results_cta'),
61	      onClick: () => this.onBuy(),
62	    });
63	
64	    // Secondary: play again → fresh run (a new start_game fires in GameScene).
65	    createButton(this, {
66	      x: cx,
67	      y: 660,
68	      texture: KEYS.ui_btn_play_again,
69	      label: t('results_play_again'),
70	      onClick: () => {
71	        playSfx(this, Sfx.ui);
72	        this.scene.start(SceneKey.Game);
73	      },
74	    });
75	
76	    // Tertiary: back to the menu — closes the Boot→…→Results→Menu loop. It's a bare
77	    // text button, so floor its hit area to MIN_TAP_TARGET_PX (§10.4) like the icon
78	    // buttons — default text-bounds would be only ~26 CSS px tall at phone scale.
79	    const menuButton = this.add
80	      .text(90, 44, `← ${t('results_menu')}`, {
81	        fontFamily: 'system-ui, sans-serif',
82	        fontSize: '22px',
83	        color: '#20272e',
84	        padding: { y: 12 },
85	      })
86	      .setOrigin(0, 0.5);
87	    enlargeHitArea(menuButton);
88	    menuButton.on(Phaser.Input.Events.POINTER_UP, () => {
89	      playSfx(this, Sfx.ui);
90	      this.scene.start(SceneKey.Menu);
91	    });
92	  }
93	
94	  private buildPromoCopyChip(x: number, y: number): void {
95	    const container = this.add.container(x, y);
96	    const chip = this.add.image(0, 0, KEYS.ui_promo_chip).setOrigin(0.5);
97	    const text = this.add
98	      .text(0, 0, `${t('results_promo_label')} ${ENV.promoCode}`, {
99	        fontFamily: 'monospace',
100	        fontSize: '26px',
101	        fontStyle: 'bold',
102	        color: '#20272e',
103	      })
104	      .setOrigin(0.5);
105	    container.add([chip, text]);
106	    // Match the hit area to the ACTUAL chip art (460×120) — the old 400×100 left
107	    // the pill's outer edges dead — floored to the comfortable tap target.
108	    const hitW = Math.max(chip.width, MIN_TAP_TARGET_PX);
109	    const hitH = Math.max(chip.height, MIN_TAP_TARGET_PX);
110	    container.setSize(hitW, hitH);
111	    container.setInteractive(
112	      new Phaser.Geom.Rectangle(-hitW / 2, -hitH / 2, hitW, hitH),
113	      Phaser.Geom.Rectangle.Contains,
114	    );
115	    if (container.input) container.input.cursor = 'pointer';
116	    container.on(Phaser.Input.Events.POINTER_UP, () => this.copyPromoCode());
117	  }
118	
119	  private async copyPromoCode(): Promise<void> {
120	    try {
121	      if (!navigator.clipboard) {
122	        return; // feature unavailable, silent no-op
123	      }
124	      await navigator.clipboard.writeText(ENV.promoCode);
125	      playSfx(this, Sfx.ui);
126	      this.showCopyConfirmation();
127	    } catch {
128	      // copy failed (e.g., no permission), silent no-op
129	      return;
130	    }
131	  }
132	
133	  private showCopyConfirmation(): void {
134	    const cx = GAME_WIDTH / 2;
135	    const label = this.add
136	      .text(cx, 410, t('results_promo_copied'), {
137	        fontFamily: 'system-ui, sans-serif',
138	        fontSize: '16px',
139	        fontStyle: 'bold',
140	        color: '#6cc04a',
141	      })
142	      .setOrigin(0.5)
143	      .setAlpha(1);
144	    this.tweens.add({
145	      targets: label,
146	      alpha: 0,
147	      duration: PROMO_COPY_FADE_MS,
148	      ease: 'Quad.in',
149	      onComplete: () => label.destroy(),
150	    });
151	  }
152	
153	  private onBuy(): void {
154	    playSfx(this, Sfx.ui);
155	    track('click_buy', { destination: buyDestination(), promo_code: ENV.promoCode });
156	    window.open(buildBuyUrl(), '_blank', 'noopener');
157	  }
158	}
