1	import Phaser from 'phaser';
2	import { KEYS } from '../config/assetManifest';
3	import { DEPTH, HUD, GAME_WIDTH, MAX_HP, MIN_TAP_TARGET_PX } from '../config/gameConfig';
4	import { t } from '../i18n/strings';
5	import { enlargeHitArea } from './Button';
6	import { GameEvents, type ArmorState } from '../scenes/gameEvents';
7	import { AudioManager } from '../systems/AudioManager';
8	import { playSfx, Sfx } from '../systems/audio';
9	import { prefersReducedMotion } from '../systems/a11y';
10	
11	export interface HudOptions {
12	  /** Invoked when the pause button is tapped. */
13	  onPause: () => void;
14	}
15	
16	export interface HudSnapshot {
17	  hp: number;
18	  score: number;
19	  progress: number;
20	}
21	
22	/**
23	 * Hud — the persistent in-run overlay (spec §6.2). It is purely a VIEW: it never
24	 * reaches into the run loop, only SUBSCRIBES to the events GameScene emits on
25	 * `scene.events` and re-paints. Hearts (shape+fill), score, a level-progress bar
26	 * (dynamic fill drawn through the frame's transparent window), plus pause + mute
27	 * controls and a small armor tell. Resets on `run:start`, freezes on `run:end`,
28	 * and removes every listener on scene shutdown (no leaks across replays).
29	 */
30	export class Hud {
31	  private readonly scene: Phaser.Scene;
32	  private readonly opts: HudOptions;
33	
34	  private readonly hearts: Phaser.GameObjects.Image[] = [];
35	  private readonly scoreText: Phaser.GameObjects.Text;
36	  private readonly progressFill: Phaser.GameObjects.Rectangle;
37	  private readonly pauseBtn: Phaser.GameObjects.Image;
38	  private readonly muteBtn: Phaser.GameObjects.Image;
39	  private readonly armorIcon: Phaser.GameObjects.Image;
40	
41	  private armorTween: Phaser.Tweens.Tween | undefined;
42	  private readonly progressUsableWidth: number;
43	  private frozen = false;
44	
45	  constructor(scene: Phaser.Scene, opts: HudOptions, initial?: HudSnapshot) {
46	    this.scene = scene;
47	    this.opts = opts;
48	    this.progressUsableWidth = HUD.progressBarWidth - HUD.progressFillInsetX * 2;
49	
50	    // ── Progress bar: frame asset + a dynamic fill drawn on top ──
51	    scene.add.image(GAME_WIDTH / 2, HUD.progressBarY, KEYS.ui_progress_bar).setDepth(DEPTH.hud);
52	    const fillLeft = GAME_WIDTH / 2 - this.progressUsableWidth / 2;
53	    this.progressFill = scene.add
54	      .rectangle(fillLeft, HUD.progressBarY, this.progressUsableWidth, HUD.progressFillHeight, HUD.progressFillColor)
55	      .setOrigin(0, 0.5)
56	      .setDepth(DEPTH.hud);
57	    this.progressFill.scaleX = 0;
58	
59	    // ── Score row ──
60	    scene.add.image(HUD.scoreIconX, HUD.scoreRowY, KEYS.ui_score_icon).setDepth(DEPTH.hud);
61	    this.scoreText = scene.add
62	      .text(HUD.scoreTextX, HUD.scoreRowY, this.scoreLabel(0), {
63	        fontFamily: 'system-ui, sans-serif',
64	        fontSize: HUD.scoreFontSize,
65	        fontStyle: 'bold',
66	        color: HUD.scoreColor,
67	        stroke: HUD.scoreStrokeColor,
68	        strokeThickness: HUD.scoreStrokeThickness,
69	      })
70	      .setOrigin(0, 0.5)
71	      .setDepth(DEPTH.hud);
72	
73	    // ── Hearts ──
74	    for (let i = 0; i < MAX_HP; i++) {
75	      this.hearts.push(
76	        scene.add.image(HUD.heartStartX + i * HUD.heartSpacing, HUD.heartY, KEYS.ui_heart_full).setDepth(DEPTH.hud),
77	      );
78	    }
79	
80	    // ── Small armor tell (hidden until armored) ──
81	    this.armorIcon = scene.add
82	      .image(HUD.armorTellX, HUD.armorTellY, KEYS.armor_pickup)
83	      .setScale(HUD.armorTellScale)
84	      .setDepth(DEPTH.hud)
85	      .setVisible(false);
86	
87	    // ── Controls (mute then pause, top-right) ──
88	    // Icon art is ~58 px inside a 64 px frame; give each a centered square hit
89	    // area ≥ MIN_TAP_TARGET_PX so the WHOLE icon (plus a forgiving margin) is
90	    // tappable on a FIT-scaled phone. The widened hit areas also widen the zone
91	    // GameScene's tap-to-jump handler excludes (it hit-tests these first).
92	    this.muteBtn = scene.add.image(HUD.muteBtnX, HUD.muteBtnY, this.muteTexture()).setDepth(DEPTH.hud);
93	    enlargeHitArea(this.muteBtn, MIN_TAP_TARGET_PX);
94	    this.muteBtn.on(Phaser.Input.Events.POINTER_UP, this.onMuteTap, this);
95	
96	    this.pauseBtn = scene.add.image(HUD.pauseBtnX, HUD.pauseBtnY, KEYS.ui_btn_pause).setDepth(DEPTH.hud);
97	    enlargeHitArea(this.pauseBtn, MIN_TAP_TARGET_PX);
98	    this.pauseBtn.on(Phaser.Input.Events.POINTER_UP, this.onPauseTap, this);
99	
100	    if (initial) {
101	      this.setHp(initial.hp);
102	      this.setScore(initial.score);
103	      this.setProgress(initial.progress);
104	    }
105	
106	    // ── Subscriptions ──
107	    const ev = scene.events;
108	    ev.on(GameEvents.hp, this.onHp, this);
109	    ev.on(GameEvents.score, this.onScore, this);
110	    ev.on(GameEvents.progress, this.onProgress, this);
111	    ev.on(GameEvents.armor, this.onArmor, this);
112	    ev.on(GameEvents.runStart, this.onRunStart, this);
113	    ev.on(GameEvents.runEnd, this.onRunEnd, this);
114	    ev.once(Phaser.Scenes.Events.SHUTDOWN, this.destroy, this);
115	  }
116	
117	  /** Re-read the shared mute state and repaint the icon (e.g. after resume). */
118	  syncMute(): void {
119	    this.muteBtn.setTexture(this.muteTexture());
120	  }
121	
122	  destroy(): void {
123	    const ev = this.scene.events;
124	    ev.off(GameEvents.hp, this.onHp, this);
125	    ev.off(GameEvents.score, this.onScore, this);
126	    ev.off(GameEvents.progress, this.onProgress, this);
127	    ev.off(GameEvents.armor, this.onArmor, this);
128	    ev.off(GameEvents.runStart, this.onRunStart, this);
129	    ev.off(GameEvents.runEnd, this.onRunEnd, this);
130	    ev.off(Phaser.Scenes.Events.SHUTDOWN, this.destroy, this);
131	    this.stopArmorTell();
132	    // Display objects are scene-owned and auto-destroyed on shutdown.
133	  }
134	
135	  // ── Event handlers ──────────────────────────────────────────────────────────
136	  private onHp(hp: number): void {
137	    if (this.frozen) return;
138	    this.setHp(hp);
139	  }
140	
141	  private onScore(score: number): void {
142	    if (this.frozen) return;
143	    this.setScore(score);
144	  }
145	
146	  private onProgress(progress: number): void {
147	    if (this.frozen) return;
148	    this.setProgress(progress);
149	  }
150	
151	  private onArmor(state: ArmorState): void {
152	    if (this.frozen) return;
153	    if (state.active) this.startArmorTell();
154	    else this.stopArmorTell();
155	  }
156	
157	  private onRunStart(): void {
158	    this.frozen = false;
159	    this.setHp(MAX_HP);
160	    this.setScore(0);
161	    this.setProgress(0);
162	    this.stopArmorTell();
163	    // Re-enable via enlargeHitArea (NOT a bare setInteractive, which would reset
164	    // the pause button to its default 64 px frame hit area) so the comfortable
165	    // tap target survives a pause→resume→run cycle.
166	    this.pauseBtn.setAlpha(1);
167	    enlargeHitArea(this.pauseBtn, MIN_TAP_TARGET_PX);
168	  }
169	
170	  private onRunEnd(): void {
171	    // Freeze the HUD in its final state; pausing is meaningless once the run ends.
172	    this.frozen = true;
173	    this.stopArmorTell();
174	    this.pauseBtn.disableInteractive();
175	    this.pauseBtn.setAlpha(HUD.frozenBtnAlpha);
176	  }
177	
178	  // ── Control taps ─────────────────────────────────────────────────────────────
179	  private onMuteTap(): void {
180	    AudioManager.toggle(this.scene.sound);
181	    this.syncMute();
182	    playSfx(this.scene, Sfx.ui);
183	  }
184	
185	  private onPauseTap(): void {
186	    if (this.frozen) return;
187	    playSfx(this.scene, Sfx.ui);
188	    this.opts.onPause();
189	  }
190	
191	  // ── Painters ─────────────────────────────────────────────────────────────────
192	  private setHp(hp: number): void {
193	    this.hearts.forEach((img, i) => {
194	      img.setTexture(i < hp ? KEYS.ui_heart_full : KEYS.ui_heart_empty);
195	    });
196	  }
197	
198	  private setScore(score: number): void {
199	    this.scoreText.setText(this.scoreLabel(score));
200	  }
201	
202	  private setProgress(progress: number): void {
203	    this.progressFill.scaleX = Phaser.Math.Clamp(progress, 0, 1);
204	  }
205	
206	  private scoreLabel(score: number): string {
207	    return `${t('hud_score')}: ${score}`;
208	  }
209	
210	  private muteTexture(): string {
211	    return AudioManager.isMuted() ? KEYS.ui_btn_mute_off : KEYS.ui_btn_mute_on;
212	  }
213	
214	  private startArmorTell(): void {
215	    this.armorIcon.setVisible(true).setScale(HUD.armorTellScale);
216	    // The icon's visibility already conveys "armored"; the pulse is decorative,
217	    // so honor prefers-reduced-motion by leaving it static (§10.4).
218	    if (this.armorTween || prefersReducedMotion()) return;
219	    this.armorTween = this.scene.tweens.add({
220	      targets: this.armorIcon,
221	      scale: { from: HUD.armorTellScale, to: HUD.armorTellPulseScale },
222	      duration: HUD.armorTellPulseMs,
223	      yoyo: true,
224	      repeat: -1,
225	      ease: 'Sine.inOut',
226	    });
227	  }
228	
229	  private stopArmorTell(): void {
230	    this.armorTween?.stop();
231	    this.armorTween = undefined;
232	    this.armorIcon.setVisible(false).setScale(HUD.armorTellScale);
233	  }
234	}
