export function createButton(scene: Phaser.Scene, opts: ButtonOptions): Phaser.GameObjects.Container {
  const container = scene.add.container(opts.x, opts.y);

  // Background art: an SVG-backed Image, or a drawn Rectangle for temporary/debug
  // and text-only buttons. The bg — NOT the container — carries the interactivity.
  let bg: Phaser.GameObjects.Image | Phaser.GameObjects.Rectangle;
  if (opts.texture) {
    bg = scene.add.image(0, 0, opts.texture).setOrigin(0.5);
  } else {
    const width = opts.width ?? 220;
    const height = opts.height ?? 64;
    bg = scene.add
      .rectangle(0, 0, width, height, 0x2b3a46)
      .setStrokeStyle(2, 0x5b6670)
      .setOrigin(0.5);
  }
  container.add(bg);

  if (opts.label !== undefined) {
    const style: Phaser.Types.GameObjects.Text.TextStyle = { ...DEFAULT_LABEL_STYLE, ...opts.labelStyle };
    const text = scene.add.text(0, 0, opts.label, style).setOrigin(0.5);
    // The label stays NON-interactive (default) so it never steals or blocks the
    // background's hit area.
    container.add(text);
  }

  // Interactivity lives on the BACKGROUND ART, never on the Container. Phaser's hit
  // test adds the object's displayOriginX/Y to the local pointer BEFORE the hitArea
  // callback, so the art normalizes to TOP-LEFT space [0,width]×[0,height]. An
  // origin-0.5 Image/Rectangle with enlargeHitArea's top-left rect therefore covers
  // the whole visible button (floored to the min tap target) — correct-by-construction,
  // the same proven path the HUD icon buttons use.
  //
  // The OLD code made the CONTAINER interactive with a CENTERED rect (−w/2 … +w/2),
  // but a Container's `displayOriginX` getter ALSO returns width/2 (Container.js:299),
  // so the same normalization shifted the effective test into the button's TOP-LEFT
  // QUADRANT — leaving ~3/4 of the art (all of the right half and bottom half,
  // including center-bottom) dead. That was the bug.
  enlargeHitArea(bg);

  // Press/hover SCALE feedback is applied to the CONTAINER (so the label scales too);
  // the bg's hit area is in bg-local space and scales WITH the art via the container
  // transform, so the effective hit region never drifts off the button.
  bg.on(Phaser.Input.Events.POINTER_OVER, () => container.setScale(HOVER_SCALE));
  bg.on(Phaser.Input.Events.POINTER_OUT, () => container.setScale(1));
  bg.on(Phaser.Input.Events.POINTER_DOWN, () => container.setScale(PRESS_SCALE));
  // Reset to the resting scale on release. On TOUCH there is no POINTER_OUT after
  // a tap, so returning to the hover scale would leave the control stuck enlarged
  // — snap back to 1; on mouse, keep the hover scale since the cursor is still on
  // the button. POINTER_OUT already handles press-then-drag-off (→ scale 1).
  bg.on(Phaser.Input.Events.POINTER_UP, (pointer: Phaser.Input.Pointer) => {
    container.setScale(pointer.wasTouch ? 1 : HOVER_SCALE);
    opts.onClick();
  });

  return container;
}

