/*
 * TEMPORARY empirical verification harness (deleted before finishing).
 *
 * Boots a real Phaser game and exercises the REAL createButton / enlargeHitArea
 * from src/ui/Button.ts through the REAL Phaser hit test (scene.input.hitTestPointer)
 * — the exact code path GameScene uses to gate tap-to-jump. It samples each control
 * at its center, four corners, and the previously-dead center-bottom / center-right,
 * and records whether the true Phaser hit test returns the control there.
 *
 * It also reproduces the OLD container-centered-rect pattern to prove the harness
 * actually detects the reported dead zones (sensitivity check).
 */
import Phaser from 'phaser';
import { createButton, enlargeHitArea } from '../src/ui/Button';

type Pt = { name: string; gx: number; gy: number };
type ControlResult = {
  control: string;
  expectLive: boolean;
  points: { name: string; live: boolean }[];
  allLive: boolean;
  anyDead: boolean;
};

function genTexture(scene: Phaser.Scene, key: string, w: number, h: number): void {
  const g = scene.add.graphics();
  g.fillStyle(0x3366cc, 1).fillRect(0, 0, w, h);
  g.generateTexture(key, w, h);
  g.destroy();
}

/** Sample points across an art box [L,R]×[T,B] in game coords (corners inset 3px). */
function samplePoints(L: number, T: number, R: number, B: number): Pt[] {
  const cx = (L + R) / 2;
  const cy = (T + B) / 2;
  const i = 3; // inset from the very edge
  return [
    { name: 'center', gx: cx, gy: cy },
    { name: 'top-left', gx: L + i, gy: T + i },
    { name: 'top-right', gx: R - i, gy: T + i },
    { name: 'bottom-left', gx: L + i, gy: B - i },
    { name: 'bottom-right', gx: R - i, gy: B - i },
    { name: 'center-bottom', gx: cx, gy: B - i }, // reported-dead spot
    { name: 'center-right', gx: R - i, gy: cy }, // reported-dead spot
    { name: 'center-top', gx: cx, gy: T + i },
    { name: 'center-left', gx: L + i, gy: cy },
  ];
}

class TestScene extends Phaser.Scene {
  private frame = 0;
  private controls: { name: string; obj: Phaser.GameObjects.GameObject; box: [number, number, number, number]; expectLive: boolean }[] = [];

  constructor() {
    super({ key: 'test' });
  }

  create(): void {
    // Pre-generate textures so nothing hits the network (fully offline / synchronous).
    genTexture(this, 'tex_play', 360, 104);
    genTexture(this, 'tex_chip', 460, 120);
    genTexture(this, 'tex_left', 200, 40);

    const interactiveChild = (c: Phaser.GameObjects.Container): Phaser.GameObjects.GameObject =>
      c.list.find((o) => (o as Phaser.GameObjects.GameObject).input != null) as Phaser.GameObjects.GameObject;

    // 1) OLD buggy pattern reproduction — container.setSize + CENTERED rect.
    {
      const px = 250, py = 150, w = 360, h = 104;
      const cont = this.add.container(px, py);
      const bg = this.add.rectangle(0, 0, w, h, 0x884444).setOrigin(0.5);
      cont.add(bg);
      cont.setSize(w, h);
      cont.setInteractive(new Phaser.Geom.Rectangle(-w / 2, -h / 2, w, h), Phaser.Geom.Rectangle.Contains);
      this.controls.push({ name: 'OLD-buggy-container(360x104)', obj: cont, box: [px - w / 2, py - h / 2, px + w / 2, py + h / 2], expectLive: false });
    }

    // 2) FIXED createButton, rectangle bg (Play-button dims 360x104).
    {
      const px = 700, py = 150, w = 360, h = 104;
      const c = createButton(this, { x: px, y: py, width: w, height: h, label: 'PLAY', onClick: () => {} });
      this.controls.push({ name: 'FIXED-createButton-rect(360x104)', obj: interactiveChild(c), box: [px - w / 2, py - h / 2, px + w / 2, py + h / 2], expectLive: true });
    }

    // 3) FIXED createButton, IMAGE bg via texture (the real Play button path).
    {
      const px = 1050, py = 150, w = 360, h = 104;
      const c = createButton(this, { x: px, y: py, texture: 'tex_play', label: 'PLAY', onClick: () => {} });
      this.controls.push({ name: 'FIXED-createButton-image(360x104)', obj: interactiveChild(c), box: [px - w / 2, py - h / 2, px + w / 2, py + h / 2], expectLive: true });
    }

    // 4) FIXED promo chip pattern — container + Image(460x120) + enlargeHitArea(chip).
    {
      const px = 320, py = 420, w = 460, h = 120;
      const cont = this.add.container(px, py);
      const chip = this.add.image(0, 0, 'tex_chip').setOrigin(0.5);
      const label = this.add.text(0, 0, 'CODE', {}).setOrigin(0.5); // non-interactive
      cont.add([chip, label]);
      enlargeHitArea(chip);
      this.controls.push({ name: 'FIXED-promoChip-image(460x120)', obj: chip, box: [px - w / 2, py - h / 2, px + w / 2, py + h / 2], expectLive: true });
    }

    // 5) FIXED createButton, pause-menu dims (264x56 art, floored to 84 tall).
    {
      const px = 780, py = 420, w = 264, h = 56;
      const c = createButton(this, { x: px, y: py, width: w, height: h, label: 'RESUME', onClick: () => {} });
      this.controls.push({ name: 'FIXED-createButton-rect(264x56)', obj: interactiveChild(c), box: [px - w / 2, py - h / 2, px + w / 2, py + h / 2], expectLive: true });
    }

    // 6) enlargeHitArea on an Image with origin (0,0.5) — the Results "← Menu" case.
    {
      const px = 1040, py = 420, w = 200, h = 40;
      const img = this.add.image(px, py, 'tex_left').setOrigin(0, 0.5);
      enlargeHitArea(img);
      // origin x=0 → art spans [px, px+w] horizontally, [py-h/2, py+h/2] vertically.
      this.controls.push({ name: 'FIXED-enlargeHitArea-originLeft(200x40)', obj: img, box: [px, py - h / 2, px + w, py + h / 2], expectLive: true });
    }
  }

  override update(): void {
    // Run after a few frames so InputPlugin._list is populated & sorted.
    if (this.frame++ !== 5) return;

    const pointer = this.input.activePointer;
    const results: ControlResult[] = this.controls.map((ctl) => {
      const [L, T, R, B] = ctl.box;
      const pts = samplePoints(L, T, R, B).map((p) => {
        pointer.x = p.gx;
        pointer.y = p.gy;
        const hits = this.input.hitTestPointer(pointer);
        return { name: p.name, live: hits.indexOf(ctl.obj) !== -1 };
      });
      const allLive = pts.every((p) => p.live);
      const anyDead = pts.some((p) => !p.live);
      return { control: ctl.name, expectLive: ctl.expectLive, points: pts, allLive, anyDead };
    });

    // A control matching expectation: live controls → all points live; buggy control → some dead.
    const okFixed = results.filter((r) => r.expectLive).every((r) => r.allLive);
    const buggyDetected = results.filter((r) => !r.expectLive).every((r) => r.anyDead);
    const verdict = { pass: okFixed && buggyDetected, okFixed, buggyDetected, results };

    const out = document.getElementById('out');
    if (out) out.textContent = JSON.stringify(verdict, null, 2);
    (window as unknown as { __RESULTS__: unknown }).__RESULTS__ = verdict;
    (window as unknown as { __DONE__: boolean }).__DONE__ = true;
  }
}

new Phaser.Game({
  type: Phaser.CANVAS, // headless-friendly; hit test is renderer-independent
  width: 1280,
  height: 720,
  parent: 'game',
  scene: [TestScene],
  banner: false,
  audio: { noAudio: true },
});

// TEMPORARY headless-Chromium CDP driver for the hit-test harness (deleted before finishing).
import { spawn } from 'node:child_process';
import http from 'node:http';
import { fileURLToPath } from 'node:url';
import path from 'node:path';
import { createRequire } from 'node:module';

const require = createRequire(import.meta.url);
const WebSocket = require('ws'); // provided transitively by vite

const dir = path.dirname(fileURLToPath(import.meta.url));
const pageUrl = 'file://' + path.join(dir, 'hittest.html');
const PORT = 9223;

function getJSON(url) {
  return new Promise((resolve, reject) => {
    http.get(url, (res) => {
      let d = '';
      res.on('data', (c) => (d += c));
      res.on('end', () => resolve(JSON.parse(d)));
    }).on('error', reject);
  });
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const chrome = spawn('chromium', [
  '--headless=new',
  '--disable-gpu',
  '--no-sandbox',
  '--no-first-run',
  '--use-gl=swiftshader',
  `--remote-debugging-port=${PORT}`,
  '--user-data-dir=/tmp/hittest-profile-' + process.pid,
  pageUrl,
], { stdio: ['ignore', 'ignore', 'inherit'] });

let ws;
async function main() {
  // Wait for the DevTools endpoint, then find the page target.
  let target;
  for (let i = 0; i < 50; i++) {
    try {
      const list = await getJSON(`http://127.0.0.1:${PORT}/json`);
      target = list.find((t) => t.type === 'page' && t.webSocketDebuggerUrl);
      if (target) break;
    } catch {}
    await sleep(200);
  }
  if (!target) throw new Error('no devtools page target');

  ws = new WebSocket(target.webSocketDebuggerUrl);
  let id = 0;
  const pending = new Map();
  ws.on('message', (raw) => {
    const msg = JSON.parse(raw.toString());
    if (msg.id && pending.has(msg.id)) {
      pending.get(msg.id)(msg);
      pending.delete(msg.id);
    }
  });
  const send = (method, params = {}) =>
    new Promise((resolve) => {
      const mid = ++id;
      pending.set(mid, resolve);
      ws.send(JSON.stringify({ id: mid, method, params }));
    });
  await new Promise((r) => ws.on('open', r));
  await send('Runtime.enable');

  // Poll for window.__DONE__, then read window.__RESULTS__.
  let verdict = null;
  for (let i = 0; i < 100; i++) {
    const r = await send('Runtime.evaluate', {
      expression: 'window.__DONE__ ? JSON.stringify(window.__RESULTS__) : ""',
      returnByValue: true,
    });
    const val = r.result && r.result.result && r.result.result.value;
    if (val) { verdict = JSON.parse(val); break; }
    await sleep(150);
  }
  if (!verdict) throw new Error('harness did not finish (no __DONE__)');
  console.log(JSON.stringify(verdict, null, 2));
  process.exitCode = verdict.pass ? 0 : 1;
}

main()
  .catch((e) => { console.error('DRIVER ERROR:', e.message); process.exitCode = 2; })
  .finally(async () => { try { ws && ws.close(); } catch {} chrome.kill('SIGKILL'); });

